  #[using="Hc Hsh"] Lemma ssm_step : forall k, (0 <= k)%Z -> (k < 2 ^ c)%Z ->
    wbytes (ssm k) (Z_to_bv 64 (sh + 8 * k)) (word_to_le_bytes 8 (Z_to_bv 64 g35)) = ssm (k + 1).
