  #[using="Hc Hsh Hok"] Lemma gc_setshadow_loop : forall (q : nat) regs k,
    ss_inv regs k -> (0 <= k)%Z -> (k + Z.of_nat q + 1 = 2 ^ c)%Z ->
    exists regs', msteps ASEGS (mkst regs (0x6456c : word) (ssm k) rom) (mkst regs' (0x644c8 : word) (ssm (2 ^ c)) rom) /\ ss_keeps regs regs'.
Proof.
