  Definition p1_inv (rg : bvmap 5 word) (i : Z) : Prop :=
    getr rg 12 = Z_to_bv 64 (h + i) /\ getr rg 10 = Z_to_bv 64 (8192 - i) /\ getr rg 13 = Z_to_bv 64 (fs + 4096 + 16384) /\ getr rg 14 = Z_to_bv 64 8191.
